public boolean canFinish(int numCourses, int[][] prerequisites) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
    int[] indeg = new int[numCourses];
    for (int[] p : prerequisites) {
        adj.get(p[1]).add(p[0]); // edge b -> a
        indeg[p[0]]++;
    }
    Queue<Integer> q = new LinkedList<>();
    for (int i = 0; i < numCourses; i++) {
        if (indeg[i] == 0) q.offer(i);
    }
    int processed = 0;
    while (!q.isEmpty()) {
        int u = q.poll();
        processed++;
        for (int v : adj.get(u)) {
            if (--indeg[v] == 0) q.offer(v);
        }
    }
    return processed == numCourses;
}

public boolean canFinish(int numCourses, int[][] prerequisites) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
    for (int[] p : prerequisites) adj.get(p[1]).add(p[0]);
    int[] color = new int[numCourses]; // 0 white, 1 gray, 2 black
    for (int i = 0; i < numCourses; i++) {
        if (color[i] == 0 && hasCycle(adj, color, i)) {
            return false;
        }
    }
    return true;
}

private boolean hasCycle(List<List<Integer>> adj, int[] color, int u) {
    color[u] = 1; // gray: on current path
    for (int v : adj.get(u)) {
        if (color[v] == 1) return true;            // back edge
        if (color[v] == 0 && hasCycle(adj, color, v)) return true;
    }
    color[u] = 2; // black: fully explored
    return false;
}

