def canFinish(self, numCourses: int, prerequisites: list[list[int]]) -> bool:
    adj: list[list[int]] = [[] for _ in range(numCourses)]
    for a, b in prerequisites:
        adj[b].append(a)
    color = [0] * numCourses  # 0 white, 1 gray, 2 black

    def has_cycle(u: int) -> bool:
        color[u] = 1  # gray: on current path
        for v in adj[u]:
            if color[v] == 1:
                return True            # back edge → cycle
            if color[v] == 0 and has_cycle(v):
                return True
        color[u] = 2  # black: done
        return False

    for i in range(numCourses):
        if color[i] == 0 and has_cycle(i):
            return False
    return True

